use crate::wasi::clocks::wall_clock;

struct Node;

/// Convert a count of days since 1970-01-01 to (year, month, day).
/// Howard Hinnant's civil-from-days algorithm.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32; // [1, 12]
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

/// Format epoch-seconds as a 10-character `YYYY-MM-DD` date (UTC).
fn format_date(seconds: u64) -> String {
    let days = (seconds / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    // Clamp the year to a 4-digit field so the result is always 10 chars.
    let y = y.rem_euclid(10_000);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // `tick.reason` is boundary input; it is not needed to answer and is
        // deliberately not forwarded anywhere.
        let _ = tick.reason;

        let now = wall_clock::now();
        RunInfo {
            date: format_date(now.seconds), // ensures: len(date) == 10
            started: now.seconds,           // ensures: started >= 0 (u64)
        }
    }
}

export!(Node);
